## `components/appInfra.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfraArgs {
    environment: "dev" | "prod";
    /**
     * DB master password supplied via secret config:
     *   pulumi config set --secret dbPassword
     */
    dbPassword: pulumi.Output<string> | string;
    // Sizing, driven by stack config
    dbInstanceClass: string;
    multiAz: boolean;
    kubeNodeCount?: number;      // informational passthrough for consumers
    enableCrossRegionReplication?: boolean;
}

export class AppInfra extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly replicaBucket?: aws.s3.BucketV2;
    public readonly database: aws.rds.Instance;
    public readonly dbSecret: aws.secretsmanager.Secret;
    public readonly serviceRole: aws.iam.Role;
    public readonly serviceUser: aws.iam.User;

    constructor(name: string, args: AppInfraArgs, opts?: pulumi.ComponentResourceOptions) {
        super("company:infra:AppInfra", name, args, opts);
        const optsD = { parent: this };
        const isProd = args.environment === "prod";

        // ---------- 1. S3 bucket: versioned + encrypted + locked down ----------
        const kmsKey = new aws.kms.Key(`${name}-assets-key`, {
            description: `${name} asset encryption key`,
            deletionWindowInDays: isProd ? 30 : 7,
        }, optsD);

        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            bucketPrefix: `${name}-assets-`,
            forceDestroy: !isProd,
        }, optsD);

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, optsD);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "aws:kms",
                    kmsMasterKeyId: kmsKey.arn,
                },
                bucketKeyEnabled: true,
            }],
        }, optsD);

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, optsD);

        // Prod-only: cross-region replication to us-west-2
        if (args.enableCrossRegionReplication) {
            const providerWest = new aws.Provider(`${name}-west`, { region: "us-west-2" }, { parent: this });
            this.replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {}, { parent: this, provider: providerWest });

            const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                        Action: "sts:AssumeRole",
                    }],
                }),
            }, optsD);

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replicationRole.id,
                policy: pulumi.jsonStringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                            Resource: [this.bucket.arn],
                        },
                        {
                            Effect: "Allow",
                            Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"],
                            Resource: [pulumi.interpolate`${this.bucket.arn}/*`],
                        },
                        {
                            Effect: "Allow",
                            Action: ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"],
                            Resource: [pulumi.interpolate`${this.replicaBucket.arn}/*`],
                        },
                    ],
                }),
            }, optsD);

            new aws.s3.BucketVersioningV2(`${name}-replica-versioning`, {
                bucket: this.replicaBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { ...optsD, provider: providerWest });

            new aws.s3.BucketReplicationConfig(`${name}-replication`, {
                bucket: this.bucket.id,
                role: replicationRole.arn,
                rules: [{
                    id: "replicate-to-west",
                    status: "Enabled",
                    filter: {},
                    deleteMarkerReplication: { status: "Disabled" },
                    destinations: [{
                        bucket: this.replicaBucket.arn,
                        storageClass: "STANDARD",
                    }],
                }],
            }, optsD);
        }

        // ---------- 2. RDS PostgreSQL ----------
        const dbName = `${name.replace(/-/g, "")}db`;

        this.database = new aws.rds.Instance(`${name}-db`, {
            identifier: `${name}-db`,
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: 20,
            maxAllocatedStorage: isProd ? 200 : 50,
            dbName,
            username: "appadmin",
            password: args.dbPassword,
            multiAz: args.multiAz,
            storageEncrypted: true,
            deletionProtection: true,
            backupRetentionPeriod: isProd ? 14 : 7,
            publiclyAccessible: false,
            skipFinalSnapshot: !isProd,
            finalSnapshotIdentifier: isProd ? `${name}-db-final` : undefined,
        }, optsD);

        // Secret: stored in Pulumi config as a secret (encrypted at rest in state).
        // We also create an AWS Secret for the app runtime; value never logged/plaintext.
        this.dbSecret = new aws.secretsmanager.Secret(`${name}-db-secret`, {}, optsD);
        new aws.secretsmanager.SecretVersion(`${name}-db-secret-value`, {
            secretId: this.dbSecret.id,
            secretString: pulumi.all([this.database.address, this.database.port])
                .apply(([addr, port]) =>
                    JSON.stringify({
                        host: addr,
                        port,
                        dbname: dbName,
                        username: "appadmin",
                        password: args.dbPassword,
                    })),
        }, optsD);

        // ---------- 3. IAM: least-privilege service account ----------
        this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
            assumeRolePolicy: JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            }),
        }, optsD);

        // Scope all statements to our specific resources — no wildcards.
        new aws.iam.RolePolicy(`${name}-service-policy`, {
            role: this.serviceRole.id,
            policy: pulumi.all([this.bucket.arn]).apply(([bucketArn]) => pulumi.jsonStringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "AssetBucketReadWrite",
                        Effect: "Allow",
                        Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
                        Resource: [`${bucketArn}/assets/*`],
                    },
                    {
                        Sid: "AssetBucketList",
                        Effect: "Allow",
                        Action: ["s3:ListBucket", "s3:GetBucketLocation"],
                        Resource: [bucketArn],
                        Condition: { StringLike: { "s3:prefix": ["assets/*"] } },
                    },
                    {
                        Sid: "ReadDbSecret",
                        Effect: "Allow",
                        Action: ["secretsmanager:GetSecretValue"],
                        Resource: [this.dbSecret.arn],
                    },
                ],
            })),
        }, optsD);

        // IAM user for CI/dev scripting; prod relies on the role above.
        this.serviceUser = new aws.iam.User(`${name}-service-user`, {}, optsD);
        const creds = new aws.iam.AccessKey(`${name}-service-user-key`, {
            user: this.serviceUser.name,
        }, optsD);

        new aws.iam.UserPolicyAttachment(`${name}-service-user-role`, {
            user: this.serviceUser.name,
            policyArn: new aws.iam.Policy(`${name}-assume-service-policy`, {
                policy: pulumi.jsonStringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Action: "sts:AssumeRole",
                        Resource: [this.serviceRole.arn],
                    }],
                }),
            }).arn,
        }, optsD);

        // Surface non-secret connection info
        pulumi.log(`DB endpoint available as output on component`, this);
        creds.secret.apply(() => {/* key material only in state */});

        this.registerOutputs({
            bucketArn: this.bucket.arn,
            databaseAddress: this.database.address,
            dbSecretArn: this.dbSecret.arn,
            serviceRoleArn: this.serviceRole.arn,
        });
    }
}
```

## `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AppInfra } from "./components/appInfra";

const cfg = new pulumi.Config();
const env = pulumi.getStack() as "dev" | "prod";

const infra = new AppInfra(`app-${env}`, {
    environment: env,
    dbPassword: cfg.requireSecret("dbPassword"),
    dbInstanceClass: cfg.get("dbInstanceClass") ?? "db.t3.micro",
    multiAz: env === "prod",
    enableCrossRegionReplication: env === "prod",
});

export const bucketName = infra.bucket.id;
export const dbEndpoint = infra.database.address;
export const dbSecretArn = infra.dbSecret.arn;
export const serviceRoleArn = infra.serviceRole.arn;
```

## Stack configs

**`Pulumi.dev.yaml`**

```yaml
config:
  aws:region: us-east-1
  app-infra:dbInstanceClass: db.t3.micro
```

**`Pulumi.prod.yaml`**

```yaml
config:
  aws:region: us-east-1
  app-infra:dbInstanceClass: db.t3.medium
```

## Usage

```bash
npm install

# Set the DB password once per stack — encrypted in Pulumi's config and state
pulumi config set --secret dbPassword 'super-secret-password'

pulumi up -c stack=dev
pulumi up -c stack=prod   # separate state file; prod changes never touch dev
```

## Notes on acceptance criteria

| Criterion | How it's met |
|---|---|
| Bucket security | KMS SSE + versioning + full public access block |
| RDS | `deletionProtection`, retention ≥ 7 days, `publiclyAccessible: false`, encrypted storage |
| Secret | `requireSecret` keeps it out of plaintext config/state output; exposed to runtime via Secrets Manager |
| IAM | Scoped to specific bucket prefix and secret ARN; no wildcard actions anywhere |
| Environment isolation | Separate Pulumi stacks = separate state files and configs |
| Prod extras | Multi-AZ, cross-region replication, final snapshots kept |

If you want this component embedded into a broader EKS-based deployment (per the scenario spine), I can add a second component that deploys the cluster matching dev/prod node specs and consumes these outputs via IRSA instead of the static IAM user.
